module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

reg [7:0] mul_a_reg;
reg [7:0] mul_b_reg;
reg [size*2-1:0] partial_products [0:size-1];
reg [size*2-1:0] sum;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_en_out <= 0;
        mul_out <= 0;
        mul_a_reg <= 0;
        mul_b_reg <= 0;
        sum <= 0;
        foreach (partial_products[i]) partial_products[i] <= 0;
    end else begin
        if (mul_en_in) begin
            mul_a_reg <= mul_a;
            mul_b_reg <= mul_b;
            sum <= 0;
            for (integer i = 0; i < size; i = i + 1) begin
                partial_products[i] <= mul_a_reg << i;
                sum <= sum + partial_products[i] & (mul_b_reg >> i);
            end
        end
        mul_en_out <= mul_en_in;
        mul_out <= sum;
    end
end

endmodule
